-- Parte 2 de 4 de la migración #16 (acc_chart_flex): plan de cuentas estándar nuevo.
-- Inspirado en el modelo de la contadora (5 niveles: 1.0.00.00.000 grupos … 1.1.01.01.001 imputables;
-- 1 Activo, 2 Pasivo, 3 Patrimonio neto, 4 Resultado del ejercicio con 4.1 Ingresos y 4.2 Egresos adentro,
-- 5 Compras) y adaptado a una SAS gastronómica responsable inscripta de Córdoba. Donde el modelo tiene el
-- mismo concepto se usa su código (IVA crédito fiscal 1.1.03.04.028, Proveedores 2.1.01.01.001…).
-- Conserva TODAS las system_key del plan anterior con el mismo tipo, lado normal, control
-- (requires_party), «¿En qué?» (purchase_selectable) y regularizadoras: el motor depende de eso.
-- 226 cuentas: 73 grupos y 153 imputables (88 con system_key, 19 de control, 51 de «¿En qué?»).
-- Solo lo usan las puestas en marcha nuevas (ningún bar está configurado todavía). Idempotente por
-- (tenant_id, code); inserta por profundidad del código y la madre sale del código (acc_code_parent):
-- los códigos de «Caja y bancos» (1.1.01.01.001, .002…) y de las tarjetas de la empresa los pone el
-- asistente con acc_next_child_code.
-- El bloque entre los marcadores @acc-seed-chart lo parsea accounting-system-keys.test.ts (toma la última
-- migración que lo tiene): una fila por línea, columnas (code, name, type, normal_side, postable,
-- system_key, requires_party, purchase_selectable, description). Es exactamente STANDARD_CHART de
-- lib/accounting/chart.ts.
create or replace function private.acc_seed_chart(p_tenant uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_level int;
  v_n int;
  v_total int := 0;
begin
  if p_tenant is null or not exists (select 1 from public.tenants t where t.id = p_tenant) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  -- Por profundidad: cada hija encuentra a su madre ya insertada.
  for v_level in 1..5 loop
    insert into public.acc_accounts (tenant_id, code, name, type, normal_side, parent_id, postable, system_key,
                                     requires_party, purchase_selectable, manual_selectable, description)
    select p_tenant, c.code, c.name, c.type::public.acc_account_type, c.normal_side::public.acc_side,
           case when v_level = 1 then null
                else (select pa.id from public.acc_accounts pa
                       where pa.tenant_id = p_tenant and pa.code = private.acc_code_parent(c.code)) end,
           c.postable, c.system_key, c.requires_party, c.purchase_selectable, true, c.description
      from (values
        -- @acc-seed-chart:begin (code, name, type, normal_side, postable, system_key, requires_party, purchase_selectable, description)
