$$;

comment on function private.acc_seed_chart(uuid) is
  'Siembra el plan de cuentas estándar (#16, estilo del modelo de 5 niveles) por profundidad. Idempotente por (tenant_id, code). Devuelve cuántas cuentas insertó.';

revoke all on function private.acc_seed_chart(uuid) from public, anon, authenticated;
